(()=>{
const $=id=>document.getElementById(id),panel=document.createElement('section');panel.className='panel review-panel';
panel.innerHTML=`<h2>Componentes y revisión</h2><p>Busca entidades, revisa sus etiquetas y conserva las correcciones en el proyecto.</p><input id="componentSearch" placeholder="ID, capa o categoría" aria-label="Buscar componente"><select id="componentList" size="6" aria-label="Componentes"></select><p id="componentCount"></p><label>Categoría <input id="componentCategory" maxlength="120"></label><label>Nota <input id="componentNote" maxlength="500"></label><label><input id="componentReviewed" type="checkbox"> Revisado por una persona</label><button id="componentSave" class="tool-button">Guardar etiqueta</button><button id="componentCsv" class="tool-button">Exportar componentes CSV</button><p id="reviewStatus" role="status">Selecciona una entidad del dibujo o de la lista.</p>`;
$('cadWorkspace').querySelector('.cad-side').prepend(panel);
function all(){return window.archCad.snapshot().data?.objects||[];}
function refresh(){const q=$('componentSearch').value.toLowerCase(),matches=all().filter(o=>[o.id,o.sourceHandle,o.layer,o.category].some(v=>String(v||'').toLowerCase().includes(q)));$('componentList').replaceChildren();for(const o of matches.slice(0,300)){const opt=document.createElement('option');opt.value=o.id;opt.textContent=`${o.sourceHandle||o.id} · ${o.category||o.layer}${o.reviewed?' ✓':''}`;$('componentList').append(opt);}$('componentList').selectedIndex=-1;$('componentCount').textContent=`${matches.length} coincidencias · se muestran hasta 300`;}
$('componentSave').disabled=true;$('componentSearch').oninput=refresh;$('componentList').onchange=e=>window.archCad.selectId(e.target.value);
window.addEventListener('cad-selection',e=>{const o=e.detail;$('componentCategory').value=o?.category||o?.layer||'';$('componentNote').value=o?.reviewNote||'';$('componentReviewed').checked=!!o?.reviewed;$('componentSave').disabled=!o;$('reviewStatus').textContent=o?'Seleccionado: '+o.id:'Selecciona una entidad.';});
window.addEventListener('cad-loaded',()=>{refresh();$('componentCategory').value='';$('componentNote').value='';$('componentReviewed').checked=false;$('componentSave').disabled=true;});
$('componentSave').onclick=()=>{if(!window.archCad.selected())return;window.archCad.updateSelected({category:$('componentCategory').value.trim(),reviewNote:$('componentNote').value.trim(),reviewed:$('componentReviewed').checked});refresh();$('reviewStatus').textContent='Etiqueta guardada en memoria. Guarda el proyecto ZIP para conservarla.';};
const cell=v=>'"'+String(v??'').replace(/^[=+@-]/,"'$&").replaceAll('"','""')+'"';
$('componentCsv').onclick=()=>{if(!all().length)return;const rows=[['id','source_id','layer','category','reviewed','note','vertices'],...all().map(o=>[o.id,o.sourceHandle,o.layer,o.category,!!o.reviewed,o.reviewNote,o.points.length])];const blob=new Blob(['\uFEFF'+rows.map(r=>r.map(cell).join(',')).join('\r\n')],{type:'text/csv;charset=utf-8'}),a=document.createElement('a'),u=URL.createObjectURL(blob);a.href=u;a.download='componentes-archglancer.csv';a.click();setTimeout(()=>URL.revokeObjectURL(u),1000);};
const demo=document.createElement('section');demo.className='panel review-panel';demo.innerHTML=`<h2>Datos para probar</h2><p>Genera un plano sintético de habitaciones, puertas y ventanas. No corresponde a un edificio real.</p><label>Semilla <input id="planSeed" type="number" value="42" min="0" max="999999"></label><button class="tool-button" id="generatePlan">Generar plano SVG</button><a href="datasets.html" target="_blank" rel="noopener">Guía de datasets y evaluación</a><p id="demoStatus" role="status">Guarda el proyecto actual antes de generar otro.</p>`;$('cadWorkspace').querySelector('.cad-side').prepend(demo);
$('generatePlan').onclick=async()=>{let seed=Number($('planSeed').value)>>>0;const original=seed;const random=()=>((seed=(Math.imul(seed,1664525)+1013904223)>>>0)/4294967296);const widths=[180+Math.floor(random()*60),180+Math.floor(random()*60)],heights=[150+Math.floor(random()*60),150+Math.floor(random()*60)];let svg=`<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 ${widths[0]+widths[1]+50} ${heights[0]+heights[1]+50}">`;let count=0;for(let row=0;row<2;row++)for(let col=0;col<2;col++){const x=20+(col?widths[0]+10:0),y=20+(row?heights[0]+10:0),w=widths[col],h=heights[row],id=++count;svg+=`<g data-name="Habitación ${id}"><path id="room-${id}" data-label="Habitación" d="M${x} ${y} h${w} v${h} h-${w} Z"/><line id="door-${id}" data-label="Puerta" x1="${x+25}" y1="${y+h}" x2="${x+25}" y2="${y+h-35}"/><line id="window-${id}" data-label="Ventana" x1="${x+w*.4}" y1="${y}" x2="${x+w*.7}" y2="${y}"/></g>`;}svg+='</svg>';await window.archCad.openFile(new File([svg],`sintetico-semilla-${original}.svg`,{type:'image/svg+xml'}));$('demoStatus').textContent='Ejemplo sintético: 4 habitaciones, 4 puertas y 4 ventanas; unidades sin calibrar. Exporta JSON para conservar la geometría.';};
})();
